SELECT 'printings' AS scope,id::text AS identity,to_jsonb(t) AS payload FROM catalog.card_printings t WHERE id=ANY(ARRAY['b7574fc2-64bf-499e-9c6c-5122ce550a62','6920ca9b-a187-4cf1-9f56-7a1a48d4762f']::uuid[]) UNION ALL SELECT 'variants',id::text,to_jsonb(t) FROM catalog.card_variants t WHERE printing_id=ANY(ARRAY['b7574fc2-64bf-499e-9c6c-5122ce550a62','6920ca9b-a187-4cf1-9f56-7a1a48d4762f']::uuid[]) UNION ALL SELECT 'names',id::text,to_jsonb(t) FROM catalog.card_names t WHERE printing_id=ANY(ARRAY['b7574fc2-64bf-499e-9c6c-5122ce550a62','6920ca9b-a187-4cf1-9f56-7a1a48d4762f']::uuid[]) OR variant_id=ANY(ARRAY['1a449bbf-02f3-4d07-8741-45475431ad07','fb44782b-ef4c-416a-a9f0-5b6adad52144']::uuid[]) UNION ALL SELECT 'sets',id::text,to_jsonb(t) FROM catalog.sets t WHERE id=ANY(ARRAY['d832f428-8d51-4ac0-a3cf-a5d38bddb88d','b5ef438a-ddcb-4093-8c9b-572639565af5']::uuid[]) UNION ALL SELECT 'sources',id::text,to_jsonb(t) FROM ingest.sources t WHERE (code IN ('scrydex','pokellector','tcgcollector','pricecharting') OR lower(base_url) LIKE '%pokellector.com%' OR lower(base_url) LIKE '%tcgcollector.com%' OR lower(base_url) LIKE '%pricecharting.com%') UNION ALL SELECT 'assets',id::text,to_jsonb(t) FROM catalog.assets t WHERE printing_id=ANY(ARRAY['b7574fc2-64bf-499e-9c6c-5122ce550a62','6920ca9b-a187-4cf1-9f56-7a1a48d4762f']::uuid[]) OR variant_id=ANY(ARRAY['1a449bbf-02f3-4d07-8741-45475431ad07','fb44782b-ef4c-416a-a9f0-5b6adad52144']::uuid[]) OR (printing_id IS NULL AND variant_id IS NULL AND set_id=ANY(ARRAY['d832f428-8d51-4ac0-a3cf-a5d38bddb88d','b5ef438a-ddcb-4093-8c9b-572639565af5']::uuid[])) UNION ALL SELECT 'links',catalogue_version_id::text||':'||asset_id::text,to_jsonb(t) FROM catalog.catalogue_version_assets t WHERE printing_id=ANY(ARRAY['b7574fc2-64bf-499e-9c6c-5122ce550a62','6920ca9b-a187-4cf1-9f56-7a1a48d4762f']::uuid[]) OR variant_id=ANY(ARRAY['1a449bbf-02f3-4d07-8741-45475431ad07','fb44782b-ef4c-416a-a9f0-5b6adad52144']::uuid[]) OR asset_id IN(SELECT id FROM catalog.assets WHERE printing_id=ANY(ARRAY['b7574fc2-64bf-499e-9c6c-5122ce550a62','6920ca9b-a187-4cf1-9f56-7a1a48d4762f']::uuid[]) OR variant_id=ANY(ARRAY['1a449bbf-02f3-4d07-8741-45475431ad07','fb44782b-ef4c-416a-a9f0-5b6adad52144']::uuid[]) OR (printing_id IS NULL AND variant_id IS NULL AND set_id=ANY(ARRAY['d832f428-8d51-4ac0-a3cf-a5d38bddb88d','b5ef438a-ddcb-4093-8c9b-572639565af5']::uuid[]))) OR(printing_id IS NULL AND variant_id IS NULL AND set_id=ANY(ARRAY['d832f428-8d51-4ac0-a3cf-a5d38bddb88d','b5ef438a-ddcb-4093-8c9b-572639565af5']::uuid[])) ORDER BY scope,identity;